   section_start("", 327516135)!
   /*Dat:*/
   RS("proxies", false, false)!
   RESOURCE_711256 = _result().get()
   /*Browser*/
   var hash = proxy_parse(RESOURCE_711256)
   if("socks5" != "auto" ){
   hash["IsHttp"] = "socks5" == "http"
   }
   var login = ""
   var password = ""
   if(login.length > 0 && password.length > 0 )
   {
   hash["name"] = login
   hash["password"] = password
   }
   if(_get_profile().length > 0)
   {
   if(hash["server"].length == 0)
   {
   native("filesystem", "removefile", _get_profile() + "/proxy.txt")
   }else
   {
   var PortNumber = hash["Port"]
   hash["Port"] = hash["Port"].toString()
   hash["DetectExternalIp"] = "true" == "true";
   hash["ChangeGeolocation"] = "false" == "true";
   hash["ChangeWebrtcIp"] = "true" == "true";
   hash["ChangeTimezone"] = "true" == "true";
   hash["ChangeBrowserLanguage"] = "true" == "true";
   hash["ip_info_method"] = "database";
   if(hash["ip_info_method"] == "custom function")
   {
   hash["ip_info_method"] = "database"
   }
   hash["ip_api_key"] = "";
   hash["ServiceURL"] = "";
   hash["IpExtractionParam"] = "";
   hash["IpExtractionMethod"] = "raw";
   native("filesystem", "writefile", JSON.stringify({path: _get_profile() + "/proxy.txt",value: JSON.stringify(hash),base64:false,append:false}))
   hash["Port"] = PortNumber
   }
   }
   set_proxy(hash["server"], hash["Port"], hash["IsHttp"], hash["name"], hash["password"])!
   sleep(1000)!
   set_proxy_extended("true" == "true", "false" == "true", "true" == "true", "true" == "true", "true" == "true", "database", "", null, "", "raw", "")!
